B.aFL=new A.fR("pronunciation","\ud83c\udfa4","Luy\u1ec7n ph\xe1t \xe2m","AI ch\u1ea5m \u0111i\u1ec3m ph\xe1t \xe2m","B\u1ea1n l\xe0 gi\xe1o vi\xean d\u1ea1y ph\xe1t \xe2m ti\u1ebfng Trung (\u0110\xe0i Loan). Khi ng\u01b0\u1eddi d\xf9ng nh\u1eadp t\u1eeb/c\xe2u, h\xe3y: 1) Phi\xean \xe2m bopomofo, 2) H\u01b0\u1edbng d\u1eabn c\xe1ch ph\xe1t \xe2m chi ti\u1ebft, 3) C\xe1c l\u1ed7i th\u01b0\u1eddng g\u1eb7p, 4) V\xed d\u1ee5 c\xe2u. Tr\u1ea3 l\u1eddi b\u1eb1ng ti\u1ebfng Vi\u1ec7t. KH\xd4NG vi\u1ebft pinyin.",B.qI,B.a7b,!1)
B.a1E=s(['Gi\u1ea3i th\xedch c\u1ea5u tr\xfac "\u628a" sentence','D\xf9ng "\u4e86" khi n\xe0o?',"Ph\xe2n bi\u1ec7t \u7684/\u5730/\u5f97"],t.s)
B.aFz=new A.fR("grammar","\ud83d\udcd6","Ng\u1eef ph\xe1p","Gi\u1ea3i th\xedch chi ti\u1ebft","B\u1ea1n l\xe0 gi\xe1o vi\xean ng\u1eef ph\xe1p ti\u1ebfng Trung. Ph\xe2n t\xedch c\u1ea5u tr\xfac c\xe2u, gi\u1ea3i th\xedch t\u1eebng th\xe0nh ph\u1ea7n, cho v\xed d\u1ee5 th\u1ef1c t\u1ebf. Tr\u1ea3 l\u1eddi b\u1eb1ng ti\u1ebfng Vi\u1ec7t. KH\xd4NG vi\u1ebft pinyin.",B.me,B.a1E,!1)
